{"command":"cat > compile.sh <<'SH'
#!/usr/bin/env bash
set -e
# create executable from python script
chmod +x gomodoutdated.py
# create small shim executable in root
cat > stub.c <<'C'
#include <unistd.h>
int main(int argc, char **argv){
    // exec the python script
    char *newargv[argc+2];
    newargv[0] = "./executable";
    for(int i=1;i<argc;i++) newargv[i]=argv[i];
    newargv[argc]=NULL;
    execv("./gomodoutdated.py", newargv);
    return 1;
}
C
gcc -O2 stub.c -o executable
chmod +x executable
rm -f stub.c
SH"}

